PREFIX dcterms: <http://purl.org/dc/terms/> 
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> 
PREFIX owl: <http://www.w3.org/2002/07/owl#> 
PREFIX awg: <https://edition.anton-webern.ch/webern-onto#> 

 CONSTRUCT { 
	 ?subject ?predicate ?object . 
 } 
 WHERE { 
	 { ?subject ?predicate ?object . FILTER (?subject = awg:M317_Sk4) } 
	 UNION 
	 { ?subject ?predicate ?object . FILTER (?object = awg:M317_Sk4) } 
 }

PREFIX dcterms: <http://purl.org/dc/terms/> 
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> 
PREFIX owl: <http://www.w3.org/2002/07/owl#> 
PREFIX awg: <https://edition.anton-webern.ch/webern-onto#> 

 CONSTRUCT { 
	 ?resource a ?resource_class ; ?precedes ?preceding_sketch . 
	 ?preceding_sketch awg:concomitates ?concomitating_object . 
	 ?concomitating_subject awg:concomitates ?preceding_sketch . 
 } 
 WHERE { 
	 ?resource a ?resource_class . 
	 ?resource ?precedes ?preceding_sketch . 
	 FILTER (?precedes = awg:precedes || ?precedes = awg:precedesScripture || ?precedes = awg:precedesContent) 
	 { ?preceding_sketch awg:concomitates ?concomitating_object . } 
	 UNION 
	 { ?concomitating_subject awg:concomitates ?preceding_sketch . } 
 }

PREFIX dcterms: <http://purl.org/dc/terms/> 
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> 
PREFIX owl: <http://www.w3.org/2002/07/owl#> 
PREFIX awg: <https://edition.anton-webern.ch/webern-onto#> 

 SELECT * 
 WHERE { 
	 { ?subject ?predicate ?object . FILTER (?subject = awg:M317_Sk4) } 
	 UNION 
	 { ?subject ?predicate ?object . FILTER (?object = awg:M317_Sk4) } 
 }

